	w0 := ws.weights[0]
	w1 := ws.weights[1]
	if len(ws.weights) >= 2 {
		if inputLen < 96 {
			w0, w1 = 0.03, 0.97
		} else if inputLen < 256 {
			w0, w1 = 0.25, 0.75
		} else {
			w0, w1 = 0.55, 0.45
		}
